const requestedSlug = typeof body.slug === 'string' ? body.slug : '';
if (requestedSlug && !/^[a-z0-9][a-z0-9-]{0,63}$/.test(requestedSlug)) {
  throw new Error('slug must match /^[a-z0-9][a-z0-9-]{0,63}$/ -- it becomes a path component and a shell argument');
}
const slug = requestedSlug || $env.REDANVIL_SLUG || 'pet-sitter';
const prompt = typeof body.prompt === 'string' && body.prompt.trim() ? body.prompt : $env.REDANVIL_PROMPT;
if (!prompt) {
  throw new Error('No prompt: POST a { prompt } body to the webhook, or set REDANVIL_PROMPT. The prd role drives the live app builder with it, and every later role builds what that PRD says, so there is no safe default.');
}
const entities = typeof body.entities === 'string' ? body.entities : ($env.REDANVIL_ENTITIES || '');
return [{ json: { repoRoot, runner, slug, prompt, entities } }];

const c = $('Slice config').first().json;
